  ('ng-640-windshark-hovercycle', 'Main Lower Thruster', 75, 'Small target: Called Shot, -4 to strike.', 2),
  ('ng-640-windshark-hovercycle', 'Lower Hover Jets (4)', 20, 'Each. Small target: Called Shot, -4 to strike.', 3),
  ('ng-640-windshark-hovercycle', 'Undercarriage Hover Jets (4, small)', 10, 'Each. Small target: Called Shot, -4 to strike.', 4),
  ('ng-640-windshark-hovercycle', 'Directional Jets (4; small)', 5, 'Each. Small target: Called Shot, -4 to strike.', 5),
  ('ng-640-windshark-hovercycle', 'Headlights (2, nose)', 2, 'Each. Small target: Called Shot, -4 to strike.', 6),
  ('ng-640-windshark-hovercycle', 'Mini-Missile/Mini-Torpedo Launch Tubes (2, front)', 15, 'Each. Small target: Called Shot, -4 to strike.', 7),
