INSERT OR IGNORE INTO vehicle_weapons (vehicle_slug, ordinal, name, damage, is_mega_damage, range, rate_of_fire, payload, bonus, note) VALUES
  ('ng-320-rampage-hovercycle', 1, 'Over and Under Nose Gun', 'Plasma (top) 4D6 M.D., laser (bottom) 2D6 M.D.; 6D6 M.D. together', 1, 'Plasma 1,600 ft (488 m); laser 2,000 ft (610 m)', 'A single shot or a simultaneous dual shot is one melee attack', 'Plasma 12, laser 40, each with two E-Clips; both unlimited on a nuclear supply', NULL, 'Standard. A fire-linked plasma ejector above a smaller laser, forward facing with a 45 degree up and down arc; 135,000 credits with its turret. The entry prints no model number.'),
  ('ng-320-rampage-hovercycle', 2, 'NG-HL40 Short-Range Light Laser', '1D6 M.D. per shot; 2D6 M.D. when both fire at one target', 1, '1,200 ft (366 m)', 'Single shot only; each counts as one melee attack', '160 single blasts, 80 per laser on two E-Clips each; unlimited on a nuclear supply', NULL, 'Standard: one in a basic turret under each wing, fire-linked so the rider shoots one or both. The entry calls them Wing Guns; the NG-HL40 (gear row ng-hl40-short-range-light-laser) is the stock fit for its payload, and any modular hovercycle energy weapon may replace it.'),
  ('ng-500-windfire-hovercycle', 1, 'NG-550W Ion Nose Gun', '6D6 M.D.', 1, '2,000 ft (610 m)', 'Each single blast is one melee attack; never fire-linked to the other weapons', 'Effectively unlimited', NULL, 'Standard. Fixed forward; fires straight ahead only. The introduction calls the nose gun a plasma cannon; the location list and the weapon entry name it ion.'),
  ('ng-500-windfire-hovercycle', 2, 'NG-540W Quad Laser Array', '2D6 M.D. single, 4D6 M.D. dual, 6D6 M.D. triple, 1D4x10+4 M.D. quadruple blast', 1, '2,000 ft (610 m)', 'One, two, three or all four at one target count as one melee attack', 'Effectively unlimited', NULL, 'Standard. Four fire-linked forward lasers inside a shovel-shaped armored shield housing, with a 30 degree upward arc.'),
  ('ng-500-windfire-hovercycle', 3, 'NG-54W Mini-Missile Tube Launchers (4)', 'By mini-missile type; armor piercing (1D4x10 M.D.) or plasma (1D6x10 M.D.) as standard, fragmentation (5D6 M.D.) against personnel', 1, 'One mile (1.6 km)', 'One at a time or volleys of 2 or 4', 'Four mini-missiles total; mini-torpedoes may be substituted', NULL, 'Standard. Four tubes in the nose under covers that flip open to fire.'),
  ('ng-su600-wave-cutter-hovercycle', 1, 'Light Ion Cannon', '4D6 M.D. on the surface; 3D6 M.D. underwater', 1, '1,000 ft (305 m) on the surface; 700 ft (213 m) underwater', 'Each blast is one melee attack', 'Effectively unlimited on nuclear or Solid Oxide; 40 blasts per charge on electric battery, with an internal port for E-Clips (6 shots each, 12 for a long E-Clip)', NULL, 'Standard. A single-barrel cannon built into the nose that works above or below water; short ranged, meant for surprise attacks. The beam weakens and spreads underwater.'),
  ('ng-su600-wave-cutter-hovercycle', 2, 'Mini-Torpedo/Mini-Missile Tubes (2)', 'By missile or torpedo type', 1, 'About one mile (1.6 km)', 'One at a time or volleys of two', 'Four total, two per tube; one tube on each side', NULL, 'Standard. Each tube takes mini-missiles or mini-torpedoes; many pilots load one of each.'),
  ('ng-640-windshark-hovercycle', 1, 'Mini-Missile/Mini-Torpedo Tubes (2)', 'By mini-missile or torpedo type; high explosive (1D4x10 M.D.) and plasma (1D6x10 M.D.) are standard', 1, 'One mile (1.6 km)', 'One at a time or volleys of two or four', 'Four total, two per launcher', NULL, 'Standard. A pair of dual launch tubes at the front, loaded with mini-missiles or with mini-torpedoes fired into the water.'),
  ('ng-640-windshark-hovercycle', 2, 'NG-HL20 Long-Range Medium Laser', '2D6 M.D.', 1, '2,000 ft (610 m)', 'Single shot only; each counts as one melee attack', '20 shots per E-Clip; ports for two E-Clips', NULL, 'Standard, fixed forward behind a nose cap that opens. The entry calls it the Concealed NG-HL20 Long-Range Medium Nose Laser; named as the gear row ng-hl20-long-range-medium-laser.');

-- Read the result back. This script asserts its OWN rows and nothing else.
SELECT 'all 5 machines are in' AS assertion, count(*) AS got, 5 AS want
  FROM vehicles WHERE slug IN ('ng-320-rampage-hovercycle', 'ng-150-streetrunner-hovercycle', 'ng-500-windfire-hovercycle', 'ng-su600-wave-cutter-hovercycle', 'ng-640-windshark-hovercycle');
SELECT 'their 53 locations are in' AS assertion, count(*) AS got, 53 AS want
  FROM vehicle_locations WHERE vehicle_slug IN ('ng-320-rampage-hovercycle', 'ng-150-streetrunner-hovercycle', 'ng-500-windfire-hovercycle', 'ng-su600-wave-cutter-hovercycle', 'ng-640-windshark-hovercycle');
SELECT 'their 9 weapon entries are in' AS assertion, count(*) AS got, 9 AS want
  FROM vehicle_weapons WHERE vehicle_slug IN ('ng-320-rampage-hovercycle', 'ng-150-streetrunner-hovercycle', 'ng-500-windfire-hovercycle', 'ng-su600-wave-cutter-hovercycle', 'ng-640-windshark-hovercycle');
SELECT 'each main body location equals mdc_main_body' AS assertion, count(*) AS got, 0 AS want
  FROM vehicles v JOIN vehicle_locations l ON l.vehicle_slug = v.slug AND l.location = 'Main Body'
  WHERE v.slug IN ('ng-320-rampage-hovercycle', 'ng-150-streetrunner-hovercycle', 'ng-500-windfire-hovercycle', 'ng-su600-wave-cutter-hovercycle', 'ng-640-windshark-hovercycle') AND l.mdc IS NOT NULL AND v.mdc_main_body IS NOT NULL AND l.mdc <> v.mdc_main_body;

